151	#[cfg(not(feature = "cargo"))]
152	#[macro_export]
153	macro_rules! command {
154	    () => {{
155	        compile_error!("`cargo` feature flag is required");
156	    }};
157	    ($name:expr) => {{
158	        compile_error!("`cargo` feature flag is required");
159	    }};
160	}
